In all, the probability of the meeting occurring is the volume of the big square pyramid minus the volumes of the smaller triangular pyramids divided by the volume of the cube: $\frac{8/3-1/6-1/6}8=\frac{7/3}8=\boxed{\frac{7}{24}}$.

question:
Compute the value of the infinite series \[
\sum_{n=2}^{\infty} \frac{n^4+3n^2+10n+10}{2^n \cdot \left(n^4+4\right)}
\]

solution:
#include <bits/stdc++.h>
using namespace std;
inline int read() {
  int x = 0, f = 1;
  char ch = getchar();
  while (ch < '0' || ch > '9') {
    if (ch == '-') f = -1;
    ch = getchar();
  }
  while (ch >= '0' && ch <= '9') {
    x = x * 10 + ch - '0';
    ch = getchar();
  }
  return x * f;
}
long double d[1001 + 5], in[1001 + 5];
int n, m, q[1001 + 5], head[1001 + 5], cnt, top, c[1001 + 5];
struct Edge {
  int u, v, a, b, c, d;
} s[2000 + 5];
struct edge {
  int to, next;
  long double w;
} e[100005];
inline void ins(int f, int t, long double w) {
  e[++cnt] = (edge){t, head[f], w};
  head[f] = cnt;
  e[++cnt] = (edge){f, head[t], 0};
  head[t] = cnt;
}
bool bfs() {
  for (int i = 1; i <= 1001; ++i) d[i] = 1e9;
  int i, j;
  for (d[q[top = i = 1] = 0] = 0; i <= top; ++i)
    for (j = c[q[i]] = head[q[i]]; j; j = e[j].next)
      if (e[j].w > 1e-11 && d[q[i]] + 1 < d[e[j].to])
        d[q[++top] = e[j].to] = d[q[i]] + 1;
  return d[1001] < 1e8;
}
long double dfs(int x, long double f) {
  if (x == 1001) return f;
  long double used = 0;
  for (int& i = c[x]; i; i = e[i].next)
    if (e[i].w > 1e-11 && d[e[i].to] == d[x] + 1) {
      long double w = dfs(e[i].to, min(f - used, e[i].w));
      used += w;
      e[i].w -= w;
      e[i ^ 1].w += w;
      if (f - used < 1e-11) return f;
    }
  return used;
}
long double Solve(long double t) {
  cnt = 1;
  memset(head, 0, sizeof(head));
  memset(in, 0, sizeof(in));
  for (int i = 1; i <= m; ++i) {
    long double l = t * s[i].a + s[i].b, r = t * s[i].c + s[i].d;
    ins(s[i].u, s[i].v, r - l);
    in[s[i].v] += l;
    in[s[i].u] -= l;
  }
  long double res = 0;
  for (int i = 1; i <= n; ++i)
    if (in[i] > 0)
      res += in[i], ins(0, i, in[i]);
    else
      ins(i, 1001, -in[i]);
  while (bfs()) res -= dfs(0, 1e9);
  return res;
}
int main() {
  n = read();
  m = read();
  for (int i = 1; i <= m; ++i)
    s[i].u = read(), s[i].v = read(), s[i].a = read(), s[i].b = read(),
    s[i].c = read(), s[i].d = read();
  long double l = 0, r = 1, ok = -1;
  for (int i = 1; i <= 50; ++i) {
    long double m1 = l + (r - l) / 3, m2 = m1 + (r - l) / 3;
    long double r1 = Solve(m1), r2 = Solve(m2);
    if (r1 < 1e-11) {
      ok = m1;
      break;
    }
    if (r2 < 1e-11) {
      ok = m2;
      break;
    }
    if (r1 < r2)
      r = m2;
    else
      l = m1;
  }
  if (ok < 0) return 0 * puts("0");
  l = 0, r = ok;
  long double L = ok, R = ok;
  for (int i = 1; i <= 50; ++i) {
    long double mid = (l + r) * 0.5;
    if (Solve(mid) < 1e-11)
      L = mid, r = mid;
    else
      l = mid;
  }
  l = ok;
  r = 1;
  for (int i = 1; i <= 50; ++i) {
    long double mid = (l + r) * 0.5;
    if (Solve(mid) < 1e-11)
      R = mid, l = mid;
    else
      r = mid;
  }
  printf("%.10lf\n", (double)(R - L));
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
inline int gi() {
  int x = 0, f = 1;
  char ch = getchar();
  while (!isdigit(ch)) {
    if (ch == '-') f = -1;
    ch = getchar();
  }
  while (isdigit(ch)) {
    x = (x << 3) + (x << 1) + ch - 48;
    ch = getchar();
  }
  return x * f;
}
template <typename T>
inline bool Max(T &a, T b) {
  return a < b ? a = b, 1 : 0;
}
template <typename T>
inline bool Min(T &a, T b) {
  return b < a ? a = b, 1 : 0;
}
const int N = 254;
const unsigned long long mod = 1e13 + 7;
int n, m;
int cnt[27], g[N][N][N];
long long ans;
char s[N];
unsigned long long v[N][N], f[N][N][N], pre[N], suf[N], val[N], sg[N], bin[N];
int idx(char c) { return c - 'a'; }
unsigned long long Rand() {
  static unsigned long long seed = 703;
  return seed = seed * 48271 % mod;
}
unsigned long long v1(int l, int r) {
  if (l > r) return 0;
  return pre[r] - pre[l - 1] * bin[r - l + 1];
}
unsigned long long v2(int l, int r) {
  if (l > r) return 0;
  return suf[l] - suf[r + 1] * bin[r - l + 1];
}
int main() {
  n = gi(), m = gi();
  for (int i = 0; i <= 25; ++i) val[i] = Rand();
  bin[0] = 1;
  for (int i = 1; i <= 250; ++i) bin[i] = bin[i - 1] * 233;
  for (int i = 1; i <= n; ++i) {
    scanf("%s", s + 1);
    for (int j = 1; j <= m; ++j) v[i][j] = idx(s[j]);
  }
  for (int i = 1; i <= n; ++i)
    for (int j = 1; j <= m; ++j) {
      memset(cnt, 0, sizeof cnt);
      int c1 = 0;
      unsigned long long hv = 0;
      for (int k = j; k <= m; ++k) {
        if (++cnt[v[i][k]] & 1)
          ++c1;
        else
          --c1;
        hv = hv ^ ((cnt[v[i][k]] - 1) * val[v[i][k]]) ^
             (cnt[v[i][k]] * val[v[i][k]]);
        f[i][j][k] = hv;
        if (k - j + 1 & 1) {
          if (c1 == 1) g[i][j][k] = 1;
        } else if (c1 == 0)
          g[i][j][k] = 1;
      }
    }
  for (int j = 1; j <= m; ++j)
    for (int k = j; k <= m; ++k) {
      for (int i = 1; i <= n; ++i)
        sg[i] = sg[i - 1] + g[i][j][k], pre[i] = pre[i - 1] * 233 + f[i][j][k];
      for (int i = n; i; --i) suf[i] = suf[i + 1] * 233 + f[i][j][k];
      for (int i = 1; i <= n; ++i)
        if (g[i][j][k]) {
          int l = 0, r = min(i - 1, n - i);
          while (l < r) {
            int mid = l + r + 1 >> 1;
            if (v1(i - mid, i - 1) == v2(i + 1, i + mid) &&
                sg[i - 1] - sg[i - mid - 1] == mid &&
                sg[i + mid] - sg[i] == mid)
              l = mid;
            else
              r = mid - 1;
          }
          ans += l + 1;
          if (i == n || f[i][j][k] != f[i + 1][j][k] || !g[i + 1][j][k])
            continue;
          l = 0, r = min(i - 1, n - i - 1);
          while (l < r) {
            int mid = l + r + 1 >> 1;
            if (v1(i - mid, i - 1) == v2(i + 2, i + mid + 1) &&
                sg[i - 1] - sg[i - mid - 1] == mid &&
                sg[i + mid + 1] - sg[i + 1] == mid)
              l = mid;
            else
              r = mid - 1;
          }
          ans += l + 1;
        }
    }
  printf("%I64d\n", ans);
  return 0;
}

#include <bits/stdc++.h>
using namespace std;
struct Add {
  long long x, d;
  int i;
  bool operator<(const Add& p) const {
    return (long long)d * p.x > (long long)p.d * x;
  }
} a[100005];
int cnt, d[100005], p[100005], sig[100005];
long long x[100005];
vector<pair<int, int>> chain[100005];
int main() {
  int i, k, n, m;
  scanf("%d%d%d", &k, &n, &m);
  for (i = 1; i <= k; i++) scanf("%I64d", &x[i]);
  for (i = 1; i <= n; i++) {
    int opt, pos, ch;
    scanf("%d%d%d", &opt, &pos, &ch);
    sig[i] = opt;
    if (opt == 1) {
      if (d[pos] < ch - x[pos]) d[pos] = ch - x[pos], p[pos] = i;
    } else if (opt == 2)
      chain[pos].push_back(make_pair(ch, i));
    else
      a[cnt++] = (Add){1, ch - 1, i};
  }
  for (i = 1; i <= k; i++) {
    if (d[i]) chain[i].push_back(make_pair(d[i], p[i]));
    sort(chain[i].rbegin(), chain[i].rend());
    for (auto e : chain[i]) {
      a[cnt++] = (Add){x[i], e.first, e.second};
      x[i] += e.first;
    }
  }
  std::sort(a, a + cnt);
  int ans = std::min(cnt, m);
  printf("%d\n", ans);
  for (i = 0; i < ans; i++)
    if (sig[a[i].i] == 1) printf("%d ", a[i].i);
  for (i = 0; i < ans; i++)
    if (sig[a[i].i] == 2) printf("%d ", a[i].i);
  for (i = 0; i < ans; i++)
    if (sig[a[i].i] == 3) printf("%d ", a[i].i);
  return 0;
}
